import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {learningProject,readLearningServiceKey} from './learning-cli-access.mjs';
import {fetchCatalogRows} from './catalog-fetch.mjs';
import {hasPrivateCredential} from './private-credential-patterns.mjs';
const root='content/editorial-drafts/education-20261128/hec-china-scholarship';
const baseline=JSON.parse(await fs.readFile(root+'/revisions/before-improvements.json','utf8'));
const post=JSON.parse(await fs.readFile(root+'/post.json','utf8'));
assert.equal(post.id,baseline.id);assert.equal(post.slug,baseline.slug);
assert.equal(hasPrivateCredential(JSON.stringify(post)),false);
assert.ok(post.content.includes('## Scholarship highlights / quick facts'));
assert.ok(post.content.includes('## Frequently asked questions'));
const key=readLearningServiceKey(),base='https://'+learningProject+'.supabase.co';
const before=await fetchCatalogRows(base,key,'blogs'),old=before.find(p=>p.id===post.id);
assert.ok(old);assert.equal(old.slug,post.slug);
const patch={content:post.content,seo:post.seo,read_time:post.readTime};
const prior={content:baseline.content,seo:baseline.seo,read_time:baseline.readTime};
const alreadyUpdated=Object.entries(patch).every(([k,v])=>JSON.stringify(old[k])===JSON.stringify(v));
if(!alreadyUpdated)for(const [k,v] of Object.entries(prior))assert.deepEqual(old[k],v,'Concurrent article edit detected: '+k);
console.log(JSON.stringify({id:post.id,existingArticles:before.length,alreadyUpdated,publish:process.argv.includes('--publish')}));
if(!process.argv.includes('--publish'))process.exit(0);
await fs.mkdir('artifacts/hec-article-improvements-20261128',{recursive:true});
await fs.writeFile('artifacts/hec-article-improvements-20261128/before.json',JSON.stringify(before));
if(!alreadyUpdated){const response=await fetch(base+'/rest/v1/blogs?id=eq.'+encodeURIComponent(post.id)+'&slug=eq.'+encodeURIComponent(post.slug),{method:'PATCH',headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(patch),signal:AbortSignal.timeout(45000)});assert.ok(response.ok,'Update failed: HTTP '+response.status);}
const after=await fetchCatalogRows(base,key,'blogs');assert.equal(after.length,before.length);
assert.deepEqual(after.find(p=>p.id===post.id),{...old,...patch});
for(const row of before.filter(p=>p.id!==post.id))assert.deepEqual(after.find(p=>p.id===row.id),row,'Unrelated record changed: '+row.id);
const receipt={savedAt:new Date().toISOString(),state:'database-updated-awaiting-static-release',id:post.id,updatedFields:Object.keys(patch),preservedOtherArticles:before.length-1,standingEditorialApproval:true};
await fs.writeFile('docs/reviews/education-news-20261128/improvement-receipt.json',JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify(receipt));
